bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
echo VIDEO_LIVE_RUNNING=PASS
docker exec "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
const c=readFileSync('/opt/videobot/owner/gateOwner.mjs','utf8');
console.log('VIDEO_GATE_STUB='+c.includes('VIDEO_TOPIC_NOT_CONNECTED'));
console.log('LIVE_THREAD_ENV_PRESENT='+Boolean(process.env.VIDEOBOT_VIDEO_SALE_THREAD_ID));
console.log('LIVE_TITLE_ENV_PRESENT='+Boolean(process.env.VIDEOBOT_VIDEO_SALE_TOPIC_TITLE));
const w=readFileSync('/opt/videobot/src/telegram/creatorWiring.mjs','utf8');
console.log('LIVE_RELEASE_GATE='+w.includes('verifyRelease:gateOwner.verifyRelease'));
NODE
docker exec "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import{readFileSync}from'node:fs';
const e=process.env,p=e.VIDEOBOT_DB_PASSWORD_FILE;
const u=e.VIDEOBOT_DATABASE_URL_FILE?readFileSync(e.VIDEOBOT_DATABASE_URL_FILE,'utf8').trim():'postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(p,'utf8').trim())+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const c=new pg.Client({connectionString:u,connectionTimeoutMillis:4000});
try{
 await c.connect();
 let q=await c.query("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND (table_name LIKE '%listing%' OR table_name LIKE '%receipt%' OR table_name='posting_topics') ORDER BY table_name");
 for(let row of q.rows)console.log('DB_TABLE='+row.table_name);
 let x=await c.query("SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='public' AND (table_name LIKE '%listing%' OR table_name LIKE '%receipt%' OR table_name='posting_topics') ORDER BY table_name,ordinal_position");
 for(let t of [...new Set(x.rows.map(z=>z.table_name))])console.log('DB_COLUMNS_'+t+'='+x.rows.filter(z=>z.table_name===t).map(z=>z.column_name).join(','));
}finally{await c.end().catch(()=>{})}
NODE
echo VIDEO_DIAG_COMPLETE=YES
